// Null selector throws NPE, after executing finally. The CFG misses that route.
static int boxedSwitch(Integer value, List<String> trace) {
    try {
        return switch(value) {
            case 0 ->
                0;
            default ->
                1;
        };
    } finally {
        trace.add("finally");
    }
}

